// ❌ OLD: Managing custom client Sets and looping in JavaScript to broadcast
const { WebSocketServer } = require('ws');
const wss = new WebSocketServer({ port: 8080 });
const clients = new Set();

wss.on('connection', (ws) => {
  clients.add(ws);
  ws.on('message', (data) => {
    // Iterating 50,000 clients in JS blocks the event loop:
    for (const client of clients) {
      if (client.readyState === 1) client.send(data);
    }
  });
  ws.on('close', () => clients.delete(ws));
});

// ✅ NEW: Built-in native topic subscription and C++ broadcasting
const server = Bun.serve({
  port: 8080,
  fetch(req, server) {
    const success = server.upgrade(req, { data: { createdAt: Date.now() } });
    return success ? undefined : new Response('Upgrade failed', { status: 400 });
  },
  websocket: {
    open(ws) {
      ws.subscribe('general-chat'); // Subscribes in native C++ layer
    },
    message(ws, message) {
      // Broadcasts to all subscribers with zero JS looping overhead!
      server.publish('general-chat', `User says: ${message}`);
    },
    close(ws) {
      ws.unsubscribe('general-chat');
    }
  }
});
